const raw = $input.first().json.content || $input.first().json.response || '';
const contactsList = $('Format Data for Bella').first().json.contacts_list || [];

let jsonStr = raw.trim();
const firstBrace = jsonStr.indexOf('{');
const lastBrace = jsonStr.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  jsonStr = jsonStr.substring(firstBrace, lastBrace + 1);
}

jsonStr = jsonStr.replace(/[\u201C\u201D\u201E\u201F\u2033\u2036]/g, '"');

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch (e) {
  try {
    const cleanedStr = jsonStr.replace(/,\s*([}\]])/g, '$1');
    parsed = JSON.parse(cleanedStr);
  } catch (err) {
    return [{ json: { response: raw } }];
  }
}

const greeting = parsed.greeting || '';
const signoff = parsed.signoff || '';
const execSummary = parsed.executive_summary || {};
const highValueLeads = parsed.high_value_leads_analysis || {};
const activityHighlights = parsed.activity_and_outreach_highlights || {};
const actionableSteps = Array.isArray(parsed.actionable_next_steps) ? parsed.actionable_next_steps : [];

function addSlackLinks(text) {
  let linkedText = text.replaceAll('**', '*');
  contactsList.forEach(c => {
    if (c.full_name && c.linkedin_url) {
      const escapedName = c.full_name.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
      const regex = new RegExp(`(?<!\\|<[^>]*)${escapedName}(?![^<]*\\|)`, 'g');
      linkedText = linkedText.replace(regex, `<${c.linkedin_url}|${c.full_name}>`);
    }
  });
  return linkedText;
}

const outputs = [];

// 1. Executive Network Growth & Pipeline Summary
if (execSummary && (execSummary.overview || (Array.isArray(execSummary.bulletpoints) && execSummary.bulletpoints.length > 0))) {
  let msg = '';
  if (greeting) msg += `${greeting}\n\n`;
  msg += `📊 *1. Executive Network Growth & Pipeline Summary* 📊\n`;
  if (execSummary.overview) msg += `${execSummary.overview}\n\n`;
  if (Array.isArray(execSummary.bulletpoints)) {
    execSummary.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 2. High-Value Prospect Leads Analysis
if (highValueLeads && (highValueLeads.overview || (Array.isArray(highValueLeads.bulletpoints) && highValueLeads.bulletpoints.length > 0))) {
  let msg = `🎯 *2. High-Value Prospect Pipeline Analysis* 🎯\n`;
  if (highValueLeads.overview) msg += `${highValueLeads.overview}\n\n`;
  if (Array.isArray(highValueLeads.bulletpoints)) {
    highValueLeads.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 3. Outreach & Activity Highlights
if (activityHighlights && (activityHighlights.overview || (Array.isArray(activityHighlights.bulletpoints) && activityHighlights.bulletpoints.length > 0))) {
  let msg = `🤝 *3. Outreach & Relationship Activity Highlights* 🤝\n`;
  if (activityHighlights.overview) msg += `${activityHighlights.overview}\n\n`;
  if (Array.isArray(activityHighlights.bulletpoints)) {
    activityHighlights.bulletpoints.forEach(b => { msg += `• ${b}\n`; });
  }
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
}

// 4. Actionable Next Steps
if (actionableSteps.length > 0) {
  let msg = `💡 *4. Actionable Next Steps for Don Jimmy* 💡\n`;
  actionableSteps.forEach(step => { msg += `• ${step}\n`; });
  if (signoff) msg += `\n${signoff}`;
  outputs.push({ json: { response: addSlackLinks(msg.trim()) } });
} else if (signoff) {
  outputs.push({ json: { response: addSlackLinks(signoff) } });
}

return outputs;
